package org.eclipse.rdf4j.sail.lmdb;

import java.io.IOException;
import java.nio.file.Path;

import org.eclipse.rdf4j.sail.lmdb.ValueStore.LanguageTagKeyMode;
import org.eclipse.rdf4j.sail.lmdb.estimation.LmdbQuadSynopsisService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Merges the value ids of case variants of one language-tagged literal in stores written before language literals were
 * keyed canonically.
 * <p>
 * Language tags compare case-insensitively ({@code "abc"@en} and {@code "abc"@EN} are one RDF term), but older stores
 * looked value ids up byte-exactly on disk and through a case-insensitive cache, so a store that received both
 * spellings while the cache was cold holds two ids for one term and is recorded as {@code language-tag-key=byte-exact}.
 * When such a store is opened, this migration
 * <ol>
 * <li>plans the merge from the value store ({@link ValueStore#planLanguageTagVariantMerge()}): each group of variants
 * keeps its smallest id, and triple terms that become equal keep theirs;</li>
 * <li>marks the persisted sketch synopsis for a rebuild (it is otherwise maintained only through the sail);</li>
 * <li>rewrites every statement that mentions a losing id ({@link TripleStore#rewriteStatementIds}), keeping context
 * counts, predicate guarantees and the Frontier mutation journal consistent;</li>
 * <li>deletes the losing values, re-keys the remaining language literals canonically and switches the value store to
 * {@code canonical} ({@link ValueStore#applyLanguageTagVariantMerge}); {@code LmdbStore} then persists the policy.</li>
 * </ol>
 * The value store and the triple store are separate LMDB environments, so no transaction spans the whole migration. It
 * is crash-safe because the value store is only modified after every statement has been rewritten: until then the next
 * open plans the same merge again and only finds the statements that are not rewritten yet; every durable prefix of the
 * value-store step is planned to completion as well. The migration therefore always rolls forward and is a no-op once
 * the store is canonical.
 */
final class LmdbLanguageTagVariantMerge {

	private static final Logger logger = LoggerFactory.getLogger(LmdbLanguageTagVariantMerge.class);

	private static final int DEFAULT_STATEMENT_BATCH_ROWS = 100_000;

	/** The durable steps of the migration, in order; reported to {@link #stepObserverForTesting}. */
	enum Step {
		PLANNED,
		SKETCH_INVALIDATED,
		STATEMENT_BATCH_COMMITTED,
		STATEMENTS_REWRITTEN,
		VALUES_MERGED
	}

	@FunctionalInterface
	interface StepObserver {
		void reached(Step step) throws IOException;
	}

	/** Test seam: notified after each step; throwing simulates a crash at that point. */
	static volatile StepObserver stepObserverForTesting;

	/** Test seam: keeps a byte-exact store byte-exact, so tests can write legacy stores through the LMDB store. */
	static volatile boolean disabledForTesting;

	/** Test seam: statements per rewrite transaction; 0 selects the default. */
	static volatile int statementBatchRowsForTesting;

	record Outcome(int variantGroups, int mergedValueIds, long rewrittenStatements) {

		static final Outcome NONE = new Outcome(0, 0, 0L);
	}

	private LmdbLanguageTagVariantMerge() {
	}

	/**
	 * Merges the case variants of language literals if the value store still keys them byte-exactly; does nothing for a
	 * canonical store.
	 *
	 * @param sketchDirectory the directory of the persisted sketch synopsis ({@code join-estimator.rjes})
	 */
	static Outcome mergeIfRequired(ValueStore valueStore, TripleStore tripleStore, Path sketchDirectory)
			throws IOException {
		if (valueStore.languageTagKeyMode() == LanguageTagKeyMode.CANONICAL || disabledForTesting) {
			return Outcome.NONE;
		}
		LanguageTagVariantMergePlan plan = valueStore.planLanguageTagVariantMerge();
		reached(Step.PLANNED);
		long rewritten = 0L;
		if (!plan.isEmpty()) {
			logger.info("Merging {} group(s) of language literals whose language tags differ only in case ({} value "
					+ "id(s) merged into another id, triple terms included)", plan.variantGroups(), plan.loserCount());
			LmdbQuadSynopsisService.markRebuildRequired(sketchDirectory);
			reached(Step.SKETCH_INVALIDATED);
			int batchRows = statementBatchRowsForTesting > 0 ? statementBatchRowsForTesting
					: DEFAULT_STATEMENT_BATCH_ROWS;
			rewritten = tripleStore.rewriteStatementIds(plan::resolve, batchRows,
					statements -> reached(Step.STATEMENT_BATCH_COMMITTED));
			reached(Step.STATEMENTS_REWRITTEN);
		}
		valueStore.applyLanguageTagVariantMerge(plan);
		reached(Step.VALUES_MERGED);
		if (!plan.isEmpty()) {
			logger.info("Merged {} group(s) of language literals whose language tags differ only in case: {} value "
					+ "id(s) merged, {} statement(s) rewritten; language literals are now keyed canonically",
					plan.variantGroups(), plan.loserCount(), rewritten);
		}
		return new Outcome(plan.variantGroups(), plan.loserCount(), rewritten);
	}

	private static void reached(Step step) throws IOException {
		StepObserver observer = stepObserverForTesting;
		if (observer != null) {
			observer.reached(step);
		}
	}
}
